/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: mount, rows, select, decide, distinct, saved, candidate, several, open, listing, reset, shown,
 *              summary
 * Tests
 *   - a single Artist entry is decided on its own row, and the saved decision names that entry and its name
 *   - several entries and a label each get a row in draft order with their roles, and every saved decision names its entry or none
 *   - an Artist another entry already reuses cannot be chosen again, and Organization candidates appear only on the label row
 *   - an append shows entry and label rows as not applied and keeps their stored decisions in the saved set
 *   - decisions of removed entries or tracks are neither shown nor saved
 *   - unsaved decisions survive a newer revision, and become stale once a decided entry or the label is renamed or newer decisions were saved
 *   - automatic values that rename entries at the same revision read the name matches again, so a new entry is offered its reuse
 *   - candidates load when Review opens, and Find matches reads them again
 *   - rows without a candidate are collapsed as preselected new records, keep the preselection by default and save no decision
 *   - name candidates keep their entry, label and Album rows expanded for an answer, and the tracks collapse once the Album is created
 *   - an append collapses a file with identical bytes on the target as a preselected reuse and one with no member as new, while a title-only member stays expanded and incomplete matches collapse nothing
 *   - a file with identical bytes on another Album is flagged and never collapsed, but needs no answer
 *   - a failed candidate read on opening shows an error and no rows, and Find matches reads them again
 *   - an entry carrying a MusicBrainz ID lists the record holding it and alias records, collapses an exact-ID reuse, and offers replace only while no record holds the ID
 *   - an Artist named with an iTunes localized name of an entry's name is listed for that entry as an iTunes localized name and holds it from a preselected create
 *   - only an entry carrying a MusicBrainz ID is offered replace, never while a record holding its ID is listed, and a saved replace takes its record from other entries
 * @end-catalog */

import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { ImportDuplicates } from './ImportDuplicates';
import type { ImportDecision } from './adminApi';
import type { ImportCandidate } from './importIdentity';
import { artistEntry, detail, entryKey, json, labelEntry, session, slotId, slotTwo, viewer } from './adminFixtures.testSupport';

/** Renders the duplicate panel for one project and returns the save callback. */
function mount(item = detail()) {
  const onSave = vi.fn(), client = new QueryClient(); client.setQueryData(['browser-session'], session);
  render(<QueryClientProvider client={client}><MemoryRouter><ImportDuplicates item={item} disabled={false} onSave={onSave} /></MemoryRouter></QueryClientProvider>);
  return onSave;
}
/** Each decision row's own label text (scope and name), without its select options. */
const rows = () => [...document.querySelectorAll('label')].map(label => [...label.childNodes].filter(node => node.nodeType === Node.TEXT_NODE).map(node => node.textContent).join(''));
const select = (index: number) => screen.getByRole('combobox', { name: `${index} · Decision` }) as HTMLSelectElement;
const decide = (index: number, value: string) => fireEvent.change(select(index), { target: { value } });
const distinct = (scope: ImportDecision['scope'], slot: string | null = null, key: string | null = null, boundName: string | null = null): ImportDecision => ({ scope, slotId: slot, entryKey: key, boundName, action: 'create-distinct', candidateId: null, candidateRevision: null });
/** The body a save sends: the decisions and the revision of the buffer's first edit. */
const saved = (decisions: ImportDecision[], expectedRevision = 1) => ({ expectedRevision, decisions });
const candidate = (kind: ImportCandidate['kind'], id: string, label: string): ImportCandidate => ({ kind, id, label, revision: `${id}-revision`, albumId: null, visibility: 'public', match: 'name', matchedSlotIds: [], automaticReuse: false });
/** Two primaries, one featured entry and a label, as the editor saves them. */
const several = () => {
  const item = detail(); item.draft.album.title = 'Synthetic Album';
  item.draft.album.artists = [{ ...artistEntry('Lorem Ensemble', entryKey(1)), joinPhrase: ' & ' }, artistEntry('Ipsum Quartet', entryKey(2)), artistEntry('Dolor Soloist', entryKey(3), 'featured')];
  item.draft.album.label = labelEntry('Sit Records'); return item;
};
/** Waits for the candidates Review loads on opening. */
const open = async () => { await screen.findByRole('button', { name: 'Save decisions' }); };
const listing = (items: ImportCandidate[], memberMatchesComplete = true) => json({ items, memberMatchesComplete });
const reset = () => { cleanup(); adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true); adminWorkspace.select('admin'); };
beforeEach(() => { reset(); vi.stubGlobal('fetch', vi.fn(async () => listing([]))); });
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); });

test('a single Artist entry is decided on its own row, and the saved decision names that entry and its name', async () => {
  const item = detail(); item.draft.album.title = 'Synthetic Album'; item.draft.album.artists = [{ ...artistEntry('Lorem Ensemble'), joinPhrase: ' & ' }];
  const onSave = mount(item); await open();
  expect(rows()).toEqual(['Artist · Lorem Ensemble · Primary', 'Album · Synthetic Album', 'Track · Untitled Album', 'Track · Untitled Album']);
  decide(1, 'create-distinct'); decide(2, 'create-distinct');
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([distinct('artist', null, entryKey(1), 'Lorem Ensemble'), distinct('album')]));
});

test('several entries and a label each get a row in draft order with their roles, and every saved decision names its entry or none', async () => {
  const onSave = mount(several()); await open();
  expect(rows()).toEqual(['Artist · Lorem Ensemble · Primary', 'Artist · Ipsum Quartet · Primary', 'Artist · Dolor Soloist · Featured', 'Label · Sit Records', 'Album · Synthetic Album', 'Track · Untitled Album', 'Track · Untitled Album']);
  for (const index of [1, 2, 3, 4, 5]) decide(index, 'create-distinct');
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([distinct('artist', null, entryKey(1), 'Lorem Ensemble'), distinct('artist', null, entryKey(2), 'Ipsum Quartet'), distinct('artist', null, entryKey(3), 'Dolor Soloist'),
    distinct('label', null, null, 'Sit Records'), distinct('album')]));
  // Only tracks may be skipped.
  expect([...select(1).options].map(option => option.value)).toEqual(['', 'create-distinct']);
  expect([...select(6).options].map(option => option.value)).toEqual(['', 'create-distinct', 'skip']);
});

test('an Artist another entry already reuses cannot be chosen again, and Organization candidates appear only on the label row', async () => {
  const artist = 'a'.repeat(24), label = 'b'.repeat(24), item = several();
  // Defensive: the server refuses two entries with one case-insensitive name, but whenever one Artist is shown on two rows the guard holds.
  item.draft.album.artists[1].name = 'lorem ensemble';
  vi.stubGlobal('fetch', vi.fn(async () => listing([candidate('artist', artist, 'Lorem Ensemble'), candidate('organization', label, 'SIT RECORDS')])));
  const onSave = mount(item); await open();
  const reuseOption = (index: number, id: string) => [...select(index).options].find(option => option.value === id);
  // Both same-named entries see the Artist; once the first reuses it, the second cannot.
  expect([reuseOption(1, artist)?.disabled, reuseOption(2, artist)?.disabled]).toEqual([false, false]);
  decide(1, artist);
  expect([reuseOption(1, artist)?.disabled, reuseOption(2, artist)?.disabled, reuseOption(3, artist)]).toEqual([false, true, undefined]);
  // The Organization is a candidate of the label row only, and links to its catalog page.
  expect([reuseOption(1, label), reuseOption(4, label)?.disabled]).toEqual([undefined, false]);
  expect(screen.getByRole('link', { name: 'SIT RECORDS' }).getAttribute('href')).toBe(`/admin/catalog/organization/${label}`);
  expect(screen.getAllByRole('link', { name: 'Lorem Ensemble' }).map(link => link.getAttribute('href'))).toEqual([`/admin/catalog/artist/${artist}`, `/admin/catalog/artist/${artist}`]);
  decide(4, label);
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([
    { scope: 'artist', slotId: null, entryKey: entryKey(1), boundName: 'Lorem Ensemble', action: 'reuse', candidateId: artist, candidateRevision: `${artist}-revision` },
    { scope: 'label', slotId: null, entryKey: null, boundName: 'Sit Records', action: 'reuse', candidateId: label, candidateRevision: `${label}-revision` }
  ]));
});

test('an append shows entry and label rows as not applied and keeps their stored decisions in the saved set', async () => {
  const album = 'c'.repeat(24), item = several();
  item.decisions = [distinct('artist', null, entryKey(1), 'Lorem Ensemble'), distinct('label', null, null, 'Sit Records'), { scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'reuse', candidateId: album, candidateRevision: 'album-revision' }];
  vi.stubGlobal('fetch', vi.fn(async () => listing([candidate('album', album, 'Synthetic Album')])));
  const onSave = mount(item); await open();
  expect(rows()).toEqual(['Album · Synthetic Album', 'Track · Untitled Album', 'Track · Untitled Album']);
  expect(screen.getAllByText('Not applied: this import adds tracks to an existing Album, so this needs no decision.')).toHaveLength(4);
  // Rows keep their positions: the entries and the label are rows 1 to 4 without a select.
  decide(6, 'create-distinct');
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([...item.decisions, distinct('track', slotId)]));
});

test('decisions of removed entries or tracks are neither shown nor saved', async () => {
  const item = several();
  item.decisions = [distinct('artist', null, entryKey(9), 'Removed Entry'), distinct('artist', null, entryKey(2), 'Ipsum Quartet'), distinct('track', '10000000-0000-4000-8000-0000000000ff'), distinct('track', slotTwo)];
  const onSave = mount(item); await open();
  expect([select(1).value, select(2).value, select(7).value]).toEqual(['', 'create-distinct', 'create-distinct']);
  decide(5, 'create-distinct');
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([distinct('artist', null, entryKey(2), 'Ipsum Quartet'), distinct('track', slotTwo), distinct('album')]));
});

test('unsaved decisions survive a newer revision, and become stale once a decided entry or the label is renamed or newer decisions were saved', async () => {
  const item = several(); mount(item); await open();
  decide(1, 'create-distinct'); decide(4, 'create-distinct');
  // A later field save, an upload or automatic values from file tags bump the revision without renaming anything: the buffer stays
  // usable, and its save still names the revision of its first edit, so decisions saved since then would conflict.
  cleanup(); const edit = { operationId: '20000000-0000-4000-8000-000000000009', kind: 'edit' as const, revision: item.revision + 2 };
  const onSave = mount({ ...several(), revision: item.revision + 3, valueRevision: 2, receipts: [edit] }); await open();
  expect([select(1).value, select(4).value, screen.queryByRole('alert')]).toEqual(['create-distinct', 'create-distinct', null]);
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([distinct('artist', null, entryKey(1), 'Lorem Ensemble'), distinct('label', null, null, 'Sit Records')], item.revision));
  // Renaming the decided entry or the label, or another administrator's saved decisions or approval after the first edit, makes
  // the buffer stale: it says so and cannot be saved until the saved decisions are loaded.
  const newer = (kind: 'decisions' | 'publish') => (next: ReturnType<typeof several>) => { next.receipts = [{ operationId: '20000000-0000-4000-8000-00000000000a', kind, revision: item.revision + 1 }]; };
  for (const change of [(next: ReturnType<typeof several>) => { next.draft.album.artists[0].name = 'Lorem Renamed'; }, (next: ReturnType<typeof several>) => { next.draft.album.label = labelEntry('Sit Records Ltd'); }, newer('decisions'), newer('publish')]) {
    cleanup(); const changed = several(); change(changed); changed.revision = item.revision + 4; mount(changed); await open();
    expect(screen.getByRole('alert').textContent).toContain('load saved version');
    expect((screen.getByRole('button', { name: 'Save decisions' }) as HTMLButtonElement).disabled).toBe(true);
  }
});

test('automatic values that rename entries at the same revision read the name matches again, so a new entry is offered its reuse', async () => {
  const artist = 'a'.repeat(24), fetches = vi.fn(async () => listing(fetches.mock.calls.length > 1 ? [candidate('artist', artist, 'Tagged Ensemble')] : []));
  vi.stubGlobal('fetch', fetches);
  const before = detail(), client = new QueryClient(); client.setQueryData(['browser-session'], session);
  const view = (item: ReturnType<typeof detail>) => <QueryClientProvider client={client}><MemoryRouter><ImportDuplicates item={item} disabled={false} onSave={vi.fn()} /></MemoryRouter></QueryClientProvider>;
  const { rerender } = render(view(before)); await open();
  expect(fetches).toHaveBeenCalledTimes(1);
  // The album step wrote an automatic entry without changing the revision.
  const after = detail(); after.valueRevision = before.valueRevision + 1; after.draft.album.artists = [artistEntry('Tagged Ensemble')]; after.automaticPaths = ['album.artists'];
  rerender(view(after));
  expect(await screen.findByRole('option', { name: /^Reuse existing · Tagged Ensemble/ })).toBeTruthy();
  expect(fetches).toHaveBeenCalledTimes(2);
  expect(String((fetches.mock.calls[1] as unknown[])[0])).toContain('/duplicate-candidates');
});

/** The collapsed state of a decision row: 'collapsed' inside a closed disclosure, 'expanded' otherwise. */
const shown = (index: number) => select(index).closest('details') ? 'collapsed' : 'expanded';
/** The summary of a collapsed row. */
const summary = (index: number) => select(index).closest('details')!.querySelector('summary')!.textContent;

test('candidates load when Review opens, and Find matches reads them again', async () => {
  const fetches = vi.fn(async () => listing([])); vi.stubGlobal('fetch', fetches);
  mount(several()); await open();
  expect(fetches).toHaveBeenCalledTimes(1); expect(String((fetches.mock.calls[0] as unknown[])[0])).toContain('/duplicate-candidates');
  fireEvent.click(screen.getByRole('button', { name: 'Find matches' }));
  await waitFor(() => expect(fetches).toHaveBeenCalledTimes(2));
  expect(await screen.findByRole('button', { name: 'Save decisions' })).toBeTruthy();
});

test('rows without a candidate are collapsed as preselected new records, keep the preselection by default and save no decision', async () => {
  const onSave = mount(several()); await open();
  expect([1, 2, 3, 4, 5, 6, 7].map(shown)).toEqual(Array(7).fill('collapsed'));
  expect(select(1)).not.toBeVisible(); expect(summary(1)).toBe('Artist · Lorem Ensemble · Primary · Preselected as new');
  expect(summary(6)).toBe('Track · Untitled Album · Preselected as new');
  // The empty choice keeps the preselection; a row that needs an answer says Review later instead.
  expect(select(1).options[0].textContent).toBe('Keep the preselected choice');
  // The row texts stay the labels' own first text, inside or outside a disclosure.
  expect(rows()).toEqual(['Artist · Lorem Ensemble · Primary', 'Artist · Ipsum Quartet · Primary', 'Artist · Dolor Soloist · Featured', 'Label · Sit Records', 'Album · Synthetic Album', 'Track · Untitled Album', 'Track · Untitled Album']);
  // An explicit choice inside a collapsed row is saved alone; the row then shows it expanded with the focus kept on its select.
  fireEvent.click(screen.getByText('Label · Sit Records · Preselected as new'));
  select(4).focus(); decide(4, 'create-distinct');
  expect([shown(4), document.activeElement]).toEqual(['expanded', select(4)]);
  // An answered row's empty choice still names the preselection it returns to.
  expect(select(4).options[0].textContent).toBe('Keep the preselected choice');
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([distinct('label', null, null, 'Sit Records')]));
  // Choosing it collapses the row again, and the focus moves to the collapsed row's summary instead of being lost.
  decide(4, '');
  const collapsed = screen.getByText('Label · Sit Records · Preselected as new');
  expect([shown(4), collapsed.tagName, document.activeElement]).toEqual(['collapsed', 'SUMMARY', collapsed]);
});

test('name candidates keep their entry, label and Album rows expanded for an answer, and the tracks collapse once the Album is created', async () => {
  const artist = 'a'.repeat(24), label = 'b'.repeat(24), album = 'c'.repeat(24);
  vi.stubGlobal('fetch', vi.fn(async () => listing([candidate('artist', artist, 'IPSUM QUARTET'), candidate('organization', label, 'sit records'), candidate('album', album, 'Synthetic Album')])));
  mount(several()); await open();
  expect([1, 2, 3, 4, 5, 6, 7].map(shown)).toEqual(['collapsed', 'expanded', 'collapsed', 'expanded', 'expanded', 'expanded', 'expanded']);
  expect(select(2).options[0].textContent).toBe('Review later');
  // An answered row with a candidate returns to no preselection, so its empty choice still says Review later.
  select(2).focus(); decide(2, 'create-distinct');
  expect([select(2).options[0].textContent, document.activeElement]).toEqual(['Review later', select(2)]);
  decide(2, '');
  expect([shown(2), document.activeElement]).toEqual(['expanded', select(2)]);
  decide(5, 'create-distinct');
  expect([shown(5), shown(6), shown(7)]).toEqual(['expanded', 'collapsed', 'collapsed']);
  // Without an Album answer again, the tracks wait for it again.
  decide(5, '');
  expect([shown(6), shown(7)]).toEqual(['expanded', 'expanded']);
});

test('an append collapses a file with identical bytes on the target as a preselected reuse and one with no member as new, while a title-only member stays expanded and incomplete matches collapse nothing', async () => {
  const album = 'c'.repeat(24), member = { ...candidate('track', 'd'.repeat(24), 'Stored Member'), albumId: album, match: 'sha256' as const, matchedSlotIds: [slotId] }, item = several();
  item.draft.tracks = [{ slotId, title: 'First', discNumber: null, trackNumber: 1 }, { slotId: slotTwo, title: 'Second', discNumber: null, trackNumber: 2 }];
  item.decisions = [{ scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'reuse', candidateId: album, candidateRevision: 'album-revision' }];
  vi.stubGlobal('fetch', vi.fn(async () => listing([candidate('album', album, 'Synthetic Album'), member])));
  const onSave = mount(item); await open();
  // Rows 1 to 4 are the not applied entries and label.
  expect([shown(5), shown(6), shown(7)]).toEqual(['expanded', 'collapsed', 'collapsed']);
  expect([summary(6), summary(7)]).toEqual(['Track · First · Preselected to reuse Stored Member: identical verified bytes on this Album', 'Track · Second · Preselected as new']);
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).not.toHaveBeenCalled();
  cleanup();
  // A member titled like the second file needs an answer; with incomplete member matches nothing collapses.
  vi.stubGlobal('fetch', vi.fn(async () => listing([candidate('album', album, 'Synthetic Album'), member, { ...candidate('track', 'e'.repeat(24), 'second'), albumId: album }])));
  mount(item); await open();
  expect([shown(6), shown(7)]).toEqual(['collapsed', 'expanded']);
  cleanup();
  vi.stubGlobal('fetch', vi.fn(async () => listing([candidate('album', album, 'Synthetic Album'), member], false)));
  mount(item); await open();
  expect([shown(6), shown(7)]).toEqual(['expanded', 'expanded']);
});

test('a file with identical bytes on another Album is flagged and never collapsed, but needs no answer', async () => {
  const other = { ...candidate('track', 'd'.repeat(24), 'Elsewhere'), albumId: 'f'.repeat(24), match: 'sha256' as const, matchedSlotIds: [slotTwo] };
  vi.stubGlobal('fetch', vi.fn(async () => listing([other])));
  mount(several()); await open();
  expect([shown(6), shown(7)]).toEqual(['collapsed', 'expanded']);
  expect(screen.getAllByText('A ready MediaTrack outside this Album has identical bytes. It may be a duplicate, is never merged, and needs no answer.')).toHaveLength(1);
  // Still preselected, so its empty choice keeps that.
  expect(select(7).options[0].textContent).toBe('Keep the preselected choice');
});

test('a failed candidate read on opening shows an error and no rows, and Find matches reads them again', async () => {
  const fetches = vi.fn(async () => fetches.mock.calls.length > 1 ? listing([]) : json({ code: 'ADMIN_IMPORT_UNAVAILABLE' }, 503)); vi.stubGlobal('fetch', fetches);
  mount(several());
  expect(await screen.findByText('The request could not be confirmed. Your saved draft is retained.', { selector: '[role=alert]' })).toBeVisible();
  expect([screen.queryByRole('combobox'), screen.queryByRole('button', { name: 'Save decisions' })]).toEqual([null, null]);
  fireEvent.click(screen.getByRole('button', { name: 'Find matches' })); await open();
  expect([fetches.mock.calls.length, screen.queryByRole('alert'), shown(1)]).toEqual([2, null, 'collapsed']);
});

test('an entry carrying a MusicBrainz ID lists the record holding it and alias records, collapses an exact-ID reuse, and offers replace only while no record holds the ID', async () => {
  const mbid = (n: number) => `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`, item = several();
  item.draft.album.artists[0] = { ...item.draft.album.artists[0], musicBrainzId: mbid(1) };
  item.draft.album.label = { name: 'Sit Records', musicBrainzId: mbid(9) };
  const holder = { ...candidate('artist', 'a'.repeat(24), 'Lorem (JP)'), match: 'musicBrainzId' as const, musicBrainzId: mbid(1) };
  const alias = { ...candidate('artist', 'c'.repeat(24), 'ロレム'), match: 'alias' as const, aliasOf: mbid(1) };
  const holding = { ...candidate('organization', 'b'.repeat(24), 'Sit Records'), musicBrainzId: mbid(5) };
  vi.stubGlobal('fetch', vi.fn(async () => listing([holder, alias, holding])));
  const onSave = mount(item); await open();
  // The exact-ID reuse is preselected and collapsed, naming the record; its other candidates (the alias) need no answer.
  expect(screen.getByText('Artist · Lorem Ensemble · Primary · Reuses Lorem (JP) (same MusicBrainz ID)')).toBeInTheDocument();
  expect([...select(1).options].map(option => option.textContent)).toEqual(expect.arrayContaining([expect.stringContaining('Same MusicBrainz ID'), expect.stringContaining('MusicBrainz alias')]));
  // The label's same-name record holds another ID: reusing it keeps that ID, and replacing it is offered since no record holds the label's.
  const options = [...select(4).options];
  expect(options.find(option => option.value === holding.id)?.textContent).toContain(`keeps its MusicBrainz ID ${mbid(5)}`);
  expect(options.find(option => option.value === `replace:${holding.id}`)?.textContent).toContain(`Reuse Sit Records and replace its MusicBrainz ID ${mbid(5)} with ${mbid(9)}`);
  decide(4, `replace:${holding.id}`);
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([{ scope: 'label', slotId: null, entryKey: null, boundName: 'Sit Records', action: 'replace', candidateId: holding.id, candidateRevision: holding.revision }]));
  cleanup();
  // A record holding the label's ID is listed, so replace is not offered for another record.
  vi.stubGlobal('fetch', vi.fn(async () => listing([holding, { ...candidate('organization', 'd'.repeat(24), 'Sit'), match: 'musicBrainzId' as const, musicBrainzId: mbid(9) }])));
  mount(item); await open();
  expect([...select(4).options].some(option => option.value.startsWith('replace:'))).toBe(false);
});

test('an Artist named with an iTunes localized name of an entry\'s name is listed for that entry as an iTunes localized name and holds it from a preselected create', async () => {
  const item = several(), localized = { ...candidate('artist', 'e'.repeat(24), 'ロレム合奏団'), match: 'localizedName' as const, localizedOf: 'Lorem Ensemble' };
  vi.stubGlobal('fetch', vi.fn(async () => listing([localized])));
  mount(item); await open();
  expect([...select(1).options].find(option => option.value === localized.id)?.textContent).toContain('iTunes localized name');
  expect([...select(2).options].some(option => option.value === localized.id)).toBe(false);
});

test('only an entry carrying a MusicBrainz ID is offered replace, never while a record holding its ID is listed, and a saved replace takes its record from other entries', async () => {
  const mbid = (n: number) => `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`, item = several();
  item.draft.album.artists[1] = { ...item.draft.album.artists[1], musicBrainzId: mbid(2) };
  // A record named like Lorem and found under an alias of Ipsum's ID, holding another ID: a candidate of both rows.
  const shared: ImportCandidate = { ...candidate('artist', 'a'.repeat(24), 'Lorem Ensemble'), match: 'alias', aliasOf: mbid(2), musicBrainzId: mbid(5) };
  item.decisions = [{ scope: 'artist', slotId: null, entryKey: entryKey(2), boundName: 'Ipsum Quartet', action: 'replace', candidateId: shared.id, candidateRevision: shared.revision }];
  vi.stubGlobal('fetch', vi.fn(async () => listing([shared])));
  mount(item); await open();
  // Lorem carries no ID: reusing the record says nothing about its ID, and nothing is replaced; Ipsum's replace already takes it.
  expect([...select(1).options].map(option => option.value)).toEqual(['', 'create-distinct', shared.id]);
  expect(select(1).options[2].textContent).not.toContain('keeps its MusicBrainz ID');
  expect(select(1).options[2].disabled).toBe(true);
  expect(select(2).value).toBe(`replace:${shared.id}`);
  expect([...select(2).options].map(option => option.value)).toEqual(['', 'create-distinct', shared.id, `replace:${shared.id}`]);
  cleanup(); reset();
  // Once a record holding Ipsum's own ID is listed, no record's ID can be replaced for it, and that record keeps nothing else.
  const holder: ImportCandidate = { ...candidate('artist', 'b'.repeat(24), 'Ipsum Quartet'), match: 'musicBrainzId', musicBrainzId: mbid(2) };
  item.decisions = [];
  vi.stubGlobal('fetch', vi.fn(async () => listing([shared, holder])));
  mount(item); await open();
  const options = [...select(2).options];
  expect(options.some(option => option.value.startsWith('replace:'))).toBe(false);
  expect(options.find(option => option.value === holder.id)!.textContent).not.toContain('keeps its MusicBrainz ID');
  expect(options.find(option => option.value === shared.id)!.textContent).toContain(`keeps its MusicBrainz ID ${mbid(5)}`);
});
